import"../../panels/security/security-legacy.js";import{TestRunner}from"../test_runner/test_runner.js";export const SecurityTestRunner={};SecurityTestRunner.dumpSecurityPanelSidebarOrigins=function(){for(const e in Security.SecurityPanelSidebarTree.OriginGroup){const n=Security.SecurityPanelSidebarTree.OriginGroup[e],t=Security.SecurityPanel.instance().sidebarTree.originGroups.get(n);if(t.hidden)continue;TestRunner.addResult("Group: "+t.title);const r=t.childrenListElement.getElementsByTagName("span");for(const e of r)"tree-element-title"!==e.className&&TestRunner.dumpDeepInnerHTML(e)}},SecurityTestRunner.dispatchRequestFinished=function(e){TestRunner.networkManager.dispatchEventToListeners(SDK.NetworkManager.Events.RequestFinished,e)};